from collections import deque
def enclosedfig(I,val,bgvals=(0,)):
    R,C=I.shape
    open_=np.isin(I,bgvals)
    reach=np.zeros_like(open_)
    dq=deque()
    for r in range(R):
        for c in (0,C-1):
            if open_[r,c] and not reach[r,c]: reach[r,c]=True;dq.append((r,c))
    for c in range(C):
        for r in (0,R-1):
            if open_[r,c] and not reach[r,c]: reach[r,c]=True;dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and open_[nr,nc] and not reach[nr,nc]:
                reach[nr,nc]=True;dq.append((nr,nc))
    return open_&~reach
