def nbcount(mask, conn=8):
    from scipy.ndimage import convolve
    k=np.ones((3,3)) if conn==8 else np.array([[0,1,0],[1,0,1],[0,1,0]])
    return convolve(mask.astype(int),k,mode='constant',cval=0)
